<?php  namespace qqworld_collector\module; use qqworld_collector\lib; class anchor extends lib { var $log_id; var $options; var $module = 'automatic-anchor'; var $count; var $settings_name = 'qqworld-collector-anchor'; public function __construct() { if ( !apply_filters( 'qqworld-collector-activated', false ) ) return; if ( apply_filters( 'qqworld-collector-activated-license', false ) && !apply_filters( 'qqworld-collector-activated-module-' . $this->module, false ) ) return; $this->log_id = $this->module; add_action( 'admin_menu', array($this, 'admin_menu') ); add_action( 'admin_init', array($this, 'register_settings') ); add_action( 'admin_enqueue_scripts', array($this, 'admin_enqueue_scripts') ); add_filter( 'qqworld-collector-script-translation-array', array($this, 'add_translation_array') ); add_filter( 'qqworld-collector-delete-post-meta-before-delete-post', array($this, 'delete_post_meta_before_delete_post') ); add_filter( 'the_content', array($this, 'add_anchor_dynamically') ); add_action( 'wp_insert_post', array($this, 'add_anchor_to_database'), 9999, 3 ); add_action( 'wp_ajax_qqworld-collector-scan-posts-and-add-anchors', array($this, 'scan_posts_and_add_anchors') ); add_action( 'wp_ajax_nopriv_qqworld-collector-scan-posts-and-add-anchors', array($this, 'scan_posts_and_add_anchors') ); add_action( 'delete_term', array($this, 'delete_term'), 10, 5 ); add_filter( 'qqworld-collector-automatic-tags-auto-wapi', array($this, 'automatic_tags_api_wapi'), 10, 2 ); add_filter( 'qqworld-collector-automatic-tags-auto-xf', array($this, 'automatic_tags_api_xf'), 10, 2 ); } public function is_exclude_terms($post_id) { $exclude_terms = apply_filters( 'qqworld-collector-automatic-anchor-exclude-terms', array()); if ($exclude_terms) { $post_type = get_post_type($post_id); $taxonomies = get_object_taxonomies('post'); if ($taxonomies) foreach ($taxonomies as $taxonomy) { $terms = get_the_terms( $post_id, $taxonomy ); if ($terms) foreach ($terms as $term) { if (in_array($term->term_id, $exclude_terms)) return true;; } } } } public function admin_menu() { $page_title = __('Automatic Anchor', $this->text_domain); $menu_title = __('Automatic Anchor', $this->text_domain); $parent_slug = $this->text_domain; $capability = !$this->options->qc_authorization_all_roles_can_modify_settings ? 'manage_options' : $this->options->qc_authorization_who_can_use; $menu_slug = 'automatic-anchor-settings'; $function = array($this, 'automatic_anchor_page'); add_submenu_page($parent_slug, $page_title, $menu_title, $capability, $menu_slug, $function); } public function add_anchor_to_database($post_ID, $post, $update) { global $wpdb; if (in_array($post->post_status, array('auto-draft', 'inherit'))) return; if ($this->options->qc_automatic_anchor_enabled && in_array($post->post_type, $this->options->qc_automatic_anchor_post_types) && $this->options->qc_automatic_anchor_save_to_database) { if ($this->is_exclude_terms($post_ID)) return; $added = get_post_meta($post_ID, 'Anchors Added', true); $added = $added ? $added : 0; if ($added < $this->options->qc_full_automatic_anchors_limit) { clean_post_cache($post); $post = get_post($post_ID); $post_content = $this->add_anchor($post->post_content, $added); if ($this->options->qc_automatic_anchor_auto_add_tags && !empty($this->tags)) wp_set_post_tags( $post_ID, implode(',', $this->tags), true ); $count = $this->count; if (strcmp($post_content, $post->post_content) !== 0) { $status = $wpdb->update( $wpdb->posts, array( 'post_content' => $post_content ), array( 'ID' => $post_ID ), array( '%s' ), array( '%d' ) ); if ($status) { $added += $count; update_post_meta($post_ID, 'Anchors Added', $added); } } } } } public function add_anchor_dynamically($content) { global $post; if ($this->options->qc_automatic_anchor_enabled && $post && isset($post->post_type) && in_array($post->post_type, $this->options->qc_automatic_anchor_post_types)) { if ($this->is_exclude_terms($post->ID)) return; if ($this->options->qc_automatic_anchor_save_to_database) { if (isset($post->ID)) { $added = get_post_meta($post->ID, 'Anchors Added', true); if ($added) return $content; } } $content = $this->add_anchor($content); } return $content; } public function get_fixed($content, $pattern) { if ( preg_match_all('/<a[^>]*?>.*?'.$pattern.'.*?<\/a>/i', $content, $matches) ) { $this->has_fixed = true; foreach ($matches[0] as $html) { $random = rand(0, 99999999); $this->from[] = "<!--{$random}-->"; $this->to[] = $html; } $content = str_replace($this->to, $this->from, $content); } if ( preg_match_all('/<[^>]*?'.$pattern.'[^<]*?>/i', $content, $matches) ) { $this->has_fixed = true; foreach ($matches[0] as $html) { $random = rand(0, 99999999); $this->from[] = "<!--{$random}-->"; $this->to[] = $html; } } if ($this->has_fixed) { $content = str_replace($this->to, $this->from, $content); } return $content; } public function add_anchor($content, $count = 0) { global $post; $this->has_fixed = false; $this->from = array(); $this->to = array(); $replaced_patterns = array(); $fixed_content = $content; if (!empty($this->options->qc_automatic_anchor_settings)) { $patterns = array(); $replacements = array(); shuffle($this->options->qc_automatic_anchor_settings); foreach ($this->options->qc_automatic_anchor_settings as $timestamp => $anchor) { $keyword = trim($anchor['keyword']); if (empty($keyword)) continue; $pattern = $this->encode_pattern($keyword); if (preg_match('/<a[^>]*?>'.$pattern.'<\/a>/i', $content)) continue; $replaced_patterns[] = $pattern; $fixed_content = $this->get_fixed($content, $pattern); if ( preg_match('/'.$pattern.'/i', $fixed_content)) { if ($count >= $this->options->qc_full_automatic_anchors_limit) break; $tax = $anchor['taxonomy']; $link = ''; if (isset($anchor['custom-link']) && !empty($anchor['custom-link'])) { $custom_link = explode('|', $anchor['custom-link']); $links = $custom_link; $links = array_filter($links, array($this, 'is_not_empty')); $link = $links[array_rand($links)]; } else { $term = get_term_by('name', $keyword, $tax); if (!$term && !is_wp_error($term)) { wp_insert_term( $keyword, $tax ); $term = get_term_by('name', $keyword, $tax); } if (!$term && !is_wp_error($term)) { $link = get_term_link($term->slug, $tax); if ($link) $this->tags[] = $keyword; } } if ($link) { $new_window = isset($anchor['new-window']) ? ' target="_blank"' : ''; $ignore_case = isset($anchor['ignore-case']) ? $anchor['ignore-case'] : ''; $bold = isset($anchor['bold']) ? 'font-weight: bold;' : ''; $color = empty($anchor['color']) ? '' : 'color: ' . $anchor['color'] . ';'; $before = '<a href="'.$link.'" style="'.$bold . $color.'"'.$new_window.'>'; $after = '</a>'; $suffix = $ignore_case ? 'i' : ''; $patterns[] = '/'.$pattern.'/' . $suffix; $replacements[] = $before . $keyword. $after; $count++; } } } $fixed_content = preg_replace($patterns, $replacements, $fixed_content, 1); } if ($this->options->qc_full_automatic_anchors_enabled) { $tags = array(); if ( $this->options->qc_full_automatic_anchors_attached_only && isset($post->ID) && $post->ID ) { $post_tags = wp_get_post_tags($post->ID); if (!empty($post_tags)) { foreach ($post_tags as $tag) { $pattern = $this->encode_pattern($tag->name); if (in_array($pattern, $replaced_patterns)) continue; $tags[] = array( 'id' => $tag->term_id, 'name' => $tag->name ); } } } if (empty($tags)) { $tags = get_transient( 'qqworld-collector-anchor-all-tags' ); if (empty($tags)) { $tags = array(); $all_tags = get_tags( array('hide_empty' => false) ); if (!empty($all_tags)) { foreach ($all_tags as $tag) { $pattern = $this->encode_pattern($tag->name); if (in_array($pattern, $replaced_patterns)) continue; $tags[] = array( 'id' => $tag->term_id, 'name' => $tag->name ); } set_transient( 'qqworld-collector-anchor-all-tags', $tags, 600 ); } } } if ($tags) { shuffle($tags); $patterns = array(); $replacements = array(); foreach ( $tags as $tag ) { extract($tag); $pattern = $this->encode_pattern($name); $fixed_content = $this->get_fixed($fixed_content, $pattern); if ( $pattern && preg_match('/'.$pattern.'/i', $fixed_content) ) { if ($count >= $this->options->qc_full_automatic_anchors_limit) break; if (preg_match('/<a[^>]*?>'.$pattern.'<\/a>/i', $content)) continue; $this->tags[] = $name; $patterns[] = '/'.$pattern.'/'; $link = get_tag_link( $id ); $before = '<a href="'.$link.'" target="_blank">'; $after = '</a>'; $replacements[] = $before . $name. $after; $count++; } } } if (!empty($patterns)) { $fixed_content = preg_replace($patterns, $replacements, $fixed_content, 1); } } if ($this->has_fixed) { $content = str_replace($this->from, $this->to, $fixed_content); } else { $content = $fixed_content; } $this->count = $count; return $content; } public function automatic_anchor_page() { require QQWORLD_COLLECTOR_DIR . 'pages' . DIRECTORY_SEPARATOR . 'automatic-anchor.php'; } public function register_settings() { register_setting($this->settings_name, $this->settings_name, array($this, 'sanitize_anchor_settings')); } public function sanitize_anchor_settings($value) { global $wpdb; $old_value = get_option($this->settings_name); $old_settings = isset($old_value['settings']) ? $old_value['settings'] : ''; if (!empty($old_settings)) { $keywords = array(); if (!empty($value['settings'])) { foreach ($old_settings as $timestamp => $v) { $key = array_search($v['keyword'], array_column($value['settings'], 'keyword')); if ($key === false) $keywords[] = $v['keyword']; } } else { foreach ($old_settings as $timestamp => $v) $keywords[] = $v['keyword']; } if (!empty($keywords)) foreach ($keywords as $keyword) { $sql = "SELECT `ID`,`post_content` FROM `{$wpdb->posts}` WHERE `post_content` REGEXP '<a.*>{$keyword}</a>'"; $results = $wpdb->get_results($sql); if (!empty($results)) foreach ($results as $result) { $wpdb->update( $wpdb->posts, array( 'post_content' => preg_replace('/<a.*?>'.$this->encode_pattern($keyword).'<\/a>/i', $keyword, $result->post_content) ), array( 'ID' => $result->ID ), array( '%s' ), array( '%d' ) ); } } } if (!empty($value['settings'])) { foreach ($value['settings'] as $timestamp => $v) { $term = $v['keyword']; $value['settings'][$timestamp]['keyword'] = $term; $taxonomy = $v['taxonomy']; if ( empty($v['custom-link']) && !term_exists( $term, $taxonomy) ) { wp_insert_term( $term, $taxonomy ); } } } if (!empty($value['import-tags'])) { $taxonomy = isset($value['import-tag-tax']) ? $value['import-tag-tax'] : 'post_tag'; $tags = explode("\r\n", $value['import-tags']); $imported = false; foreach ($tags as $tag) { $term = trim($tag); if ( !term_exists( $term, $taxonomy) ) { $imported = true; wp_insert_term( $term, $taxonomy ); } } if ($imported) add_settings_error( 'myUniqueIdentifier', esc_attr( 'settings_updated' ), __('Successfully imported tags.', $this->text_domain), 'updated' ); } if (!empty($value['automatic-tags'])) { if (isset($value['automatic-tags']['scan'])) { $post_types = isset($value['automatic-tags']['post-type']) ? $value['automatic-tags']['post-type'] : 'post'; set_time_limit($this->options->qc_stress_timeout); $i = 0; while ($i>-1) { $args = array( 'posts_per_page' => 1000, 'offset' => $i*1000, 'post_type' => $post_types ); $posts = get_posts($args); if (!empty($posts)) { foreach ($posts as $post) { do_action( 'qqworld-collector-add-tags-to-post', $post->ID, $post, true ); } $i++; } else { $i = -1; } } } } return $value; } public function admin_enqueue_scripts() { $screen = get_current_screen(); if (strstr($screen->id, 'automatic-anchor-settings')) { wp_enqueue_script( 'qqworld-collector-anchor-admin' ); wp_enqueue_script( 'wp-color-picker' ); wp_enqueue_style( 'wp-color-picker' ); wp_enqueue_script( 'jquery-ui-core' ); wp_enqueue_script( 'jquery-ui-sortable' ); wp_enqueue_style('animate'); wp_enqueue_script('noty'); wp_enqueue_style('noty'); } } public function add_translation_array($translation_array) { global $post; $screen = get_current_screen(); if (strstr($screen->id, 'automatic-anchor-settings')) { $translation_array['automatic_anchor_activated'] = apply_filters( 'qqworld-collector-activated-module-automatic-anchor', false ); $taxonomies = get_taxonomies(array('public' => 1, 'show_ui' => 1, 'hierarchical' => 0), 'objects'); $translation_array['taxonomies'] = array(); foreach ($taxonomies as $slug => $taxonomy) { $translation_array['taxonomies'][$slug] = $taxonomy->label; } $translation_array['text']['are_your_sure_scan_posts_and_add_anchors'] = __('Are your sure?<br />Once you start scanning, all posts will be anchored,<br />so just in case, it is recommended to back up the database first.', $this->text_domain); $translation_array['text']['u_can_close_window'] = __('You can close current window now, no need to wait fot finished.', $this->text_domain); $translation_array['text']['all_posts_has_scanned'] = __('All posts has been scanned.', $this->text_domain); } return $translation_array; } public function scan_posts_and_add_anchors() { set_time_limit($this->options->qc_stress_timeout); $args = array( 'posts_per_page' => -1, 'post_type' => get_post_types(array('public ' => 1, 'show_ui' => 1)), 'post_status' => 'any', 'meta_key' => 'Anchors Added', 'meta_compare' => 'NOT EXISTS' ); $posts = get_posts($args); if (!empty($posts)) foreach ($posts as $post) { wp_update_post($post); } exit; } public function delete_post_meta_before_delete_post($post_metas) { $post_metas[] = 'Anchors Added'; return $post_metas; } public function delete_term($term, $tt_id, $taxonomy, $deleted_term, $object_ids) { global $wpdb; if (!is_taxonomy_hierarchical($taxonomy)) { $keyword = $deleted_term->name; $sql = "SELECT `ID`,`post_content` FROM `{$wpdb->posts}` WHERE `post_content` REGEXP '<a.*>{$keyword}</a>'"; $results = $wpdb->get_results($sql); if (!empty($results)) foreach ($results as $result) { $wpdb->update( $wpdb->posts, array( 'post_content' => preg_replace('/<a.*?>'.$this->encode_pattern($keyword).'<\/a>/i', $keyword, $result->post_content) ), array( 'ID' => $result->ID ), array( '%s' ), array( '%d' ) ); } } } public function automatic_tags_api_wapi($data, $fields) { $secret = $this->options->qc_automatic_tags_auto_wapi_secret; $data = array( 'appid'=> $this->options->qc_automatic_tags_auto_wapi_appid, 'format'=> 'json', 'sentence'=> implode(', ', $fields), 'time'=> time(), ); ksort($data); $md5String = ''; foreach ($data as $key => $val) { if (strlen($val) > 0) { $md5String .= $key . $val; } } $sign = md5($md5String.$secret); $data['sign'] = $sign; $args = array( 'sslverify' => false, 'body' => $data ); $response = wp_remote_post($this->options->qc_automatic_tags_auto_wapi_app_url, $args); $body = wp_remote_retrieve_body($response); $body = json_decode($body, true); do_action( 'qqworld-collector-log', $this->log_id, 'Automatic Tags ($body):', print_r($body, true) ); if ($body && $body['codeid'] == 10000) { $data = $body['retdata']['seg_list']; } return $data; } public function automatic_tags_api_xf($data, $fields) { $api = "http://ltpapi.xfyun.cn/v1/ke"; $XAppid = $this->options->qc_automatic_tags_auto_xf_appid; $Apikey = $this->options->qc_automatic_tags_auto_xf_apikey; $XCurTime = time(); $XParam = ""; $XCheckSum = ""; $Param = array( "type" => "dependent", ); $Post = array( 'text' => substr(implode(', ', $fields), 0 , 30000) ); $XParam = base64_encode(json_encode($Param)); $XCheckSum = md5($Apikey.$XCurTime.$XParam); $headers = array(); $headers[] = 'X-CurTime:'.$XCurTime; $headers[] = 'X-Param:'.$XParam; $headers[] = 'X-Appid:'.$XAppid; $headers[] = 'X-CheckSum:'.$XCheckSum; $headers[] = 'Content-Type:application/x-www-form-urlencoded; charset=utf-8'; $postdata = http_build_query($Post); $options = array( 'http' => array( 'method' => 'POST', 'header' => $headers, 'content' => $postdata, 'timeout' => 15*60 ) ); $context = stream_context_create($options); $result = file_get_contents($api, false, $context); $result = json_decode($result, true); if ($result && $result['code'] == 0 && count($result['data']['ke'])) { $data = array(); foreach ($result['data']['ke'] as $d) { $data[] = $d['word']; } } return $data; } }